static void textPattern(std::vector<uint32_t>&p,int w,int h,const std::vector<rendering::Rect>&clip){for(auto r:clip)for(int y=r.top;y<r.bottom;++y)for(int x=r.left;x<r.right;++x)if(y%17<3&&x%23<11)p[y*w+x]=0xfff6d7;}
